const stages = $input.first().json.body.stages;
const stagesArray = Object.keys(stages)
  .sort((a, b) => parseInt(a) - parseInt(b))
  .map(stageKey => {
    const stage = stages[stageKey];
    const workers = Object.keys(stage.tasks).map(workerName => {
      const task = stage.tasks[workerName];
      return {
        sessionId: $input.first().json.body.sessionId,
        stageNumber: stage.stageNumber,
        worker: workerName,
        port: task.port,
        taskPrompt: task.fullPrompt
      };
    });
    return {
      stageNumber: stage.stageNumber,
      status: stage.status,
      tasks: workers  // Now as array instead of dict
    };
  });

return { stagesArray };

// Get stage number from current loop item
const currentStage = $('Loop Over Items').first().json.stageNumber;
const previousStage = currentStage - 1;
const sessionId = $input.first().json.sessionId;

if (currentStage === 1) {
  return {
    sessionId: sessionId,
    stageNumber: 1, 
    canProceed: true,
    reason: "First stage"
  };
}

// Now get the document (must come from previous MongoDB read or Set node)
const doc = $input.first().json;

if (!doc.stages || !doc.stages[previousStage]) {
  return {
    stageNumber: currentStage,
    canProceed: false,
    reason: `Stage ${previousStage} not found`
  };
}

const previousStageData = doc.stages[previousStage];
const workers = Object.keys(previousStageData.tasks);

//const allComplete = workers.every(w => 
//  previousStageData.tasks[w].status === "completed"
//);
const allComplete = previousStageData.status === "completed";

return {
  sessionId: sessionId,
  canProceed: allComplete,
  previousStage: previousStage,
  stageNumber: currentStage,
  completedWorkers: workers.filter(w => previousStageData.tasks[w].status === "completed").length,
  totalWorkers: workers.length
};
